(async()=>{'use strict';const $=id=>document.getElementById(id),node=(t,text)=>{const e=document.createElement(t);if(text!==undefined)e.textContent=text;return e;};const form=$('landing-profile-form');if(form)form.onsubmit=e=>{e.preventDefault();try{sessionStorage.setItem('bonga-profile-name',$('landing-brand').value.trim());}catch{}location.href='/fashion-service.html#designer';};async function refresh(){try{const r=await fetch('/api/public/status'),s=await r.json();if(!r.ok)throw Error();if($('landing-service-state'))$('landing-service-state').textContent='Workspace '+s.workspace.toLowerCase()+' · Checked '+new Date(s.checkedAt).toLocaleTimeString()+'. AI '+s.ai.toLowerCase()+'.';}catch{if($('landing-service-state'))$('landing-service-state').textContent='Workspace status unavailable. Please retry shortly.';}}refresh();setInterval(()=>{if(!document.hidden)refresh();},60000);
try{const r=await fetch('/api/public/packages'),data=await r.json();if(!r.ok)throw Error();const cards=$('package-cards');if(!cards)return;for(const p of data.packages){const article=node('article'),h=node('h3',p.name),price=node('div');price.className='package-price';price.append(document.createTextNode('R'+p.price),node('small',' / month'));const list=node('ul');for(const line of [p.companies+' company profile'+(p.companies===1?'':'s'),p.products+' published collection designs',p.files+' saved media files',p.storageMB===1024?'1 GB media storage':p.storageMB+' MB media storage',p.cameras+' phone camera'+(p.cameras===1?'':'s'),p.workAreas+' supported work areas'])list.append(node('li',line));const button=node('button','Request '+p.name);button.onclick=async()=>{button.disabled=true;$('package-state').textContent='Saving your package request…';try{const response=await fetch('/api/designer/package',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tier:p.id})}),result=await response.json();if(response.status===401){sessionStorage.setItem('bonga-requested-tier',p.id);location.href='/signin-with-chatgpt?return_to='+encodeURIComponent('/#packages');return;}if(!response.ok)throw Error(result.error);$('package-state').textContent=result.status;}catch(e){$('package-state').textContent=e.message||'Package request unavailable.';}finally{button.disabled=false;}};article.append(h,price,list,button,node('p','Request only · activation pending'));cards.append(article);}const l=data.currentLimits;$('current-service-limits').textContent='Current workspace ceiling: '+l.websites+' hosted storefront, '+l.publishedProducts+' published designs, '+l.files+' files, 1 GB media storage and '+l.cameras+' camera slots. Package allowances are not activated yet.';const current=await fetch('/api/designer/package');if(current.ok){const d=await current.json();if(d.request){const plan=data.packages.find(p=>p.id===d.request.tier);$('package-state').textContent=(plan?.name||d.request.tier)+' requested · awaiting activation confirmation.';}else if(sessionStorage.getItem('bonga-requested-tier')){$('package-state').textContent='You are signed in. Select your package again to confirm your request.';}}}catch{$('package-state')&&($('package-state').textContent='Packages unavailable. Please try again shortly.');}
})();
